<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, reactive, ref, watch } from 'vue';
import { ElButton, ElCard } from 'element-plus';
import { getTopology, geoNames, type DeviceStatus, type GeoData, type GeoItem, type GeoLevel, type GeoQuery } from './geography';
import type { Context, Role, Scenario } from './dashboard';
import GeoChart from './GeoChart.vue';
import { geoListPage, type GeoDirection, type GeoSort } from './geo-list';
import { geoLegendOptions } from './geo-status';
import './dashboard.css';
import './geography.css';
type Filters = { tenantId: string; productId: string; status: string; continent: string; countryCode: string; nodeId: string; range: string; from: string; to: string };
type Crumb = { level: GeoLevel; id: string; name: string };
const tenants: Record<string, string> = { all: '全部租户', ten_202609_001: '华东智联', ten_202609_002: '全球能源' };
const products: Record<string, string> = { '': '全部产品', prod_as_001: '工业传感器', prod_as_002: '能源网关' };
const statuses: Record<string, string> = { '': '全部状态', unactivated: '未激活', online: '在线', offline: '离线', fault: '故障', maintenance: '维护', alarm: '告警' };
const initialFilters = (): Filters => ({ tenantId: localStorage.getItem('iot-atlas-current-tenant-v1') || 'all', productId: '', status: '', continent: '', countryCode: '', nodeId: '', range: '24h', from: '', to: '' });
function initialLocation(): { filters: Filters; crumbs: Crumb[] } {
  const params = new URLSearchParams(location.search), filters = initialFilters();
  const from = params.get('from'), to = params.get('to');
  if (from && to && Number.isFinite(Date.parse(from)) && Number.isFinite(Date.parse(to)) && Date.parse(from) < Date.parse(to) && Date.parse(to) - Date.parse(from) <= 30 * 86_400_000) { filters.from = from; filters.to = to; filters.range = 'custom'; }
  filters.tenantId = params.get('tenant') || filters.tenantId;
  const continent = params.get('continent') || params.get('region') || '', country = params.get('country') || '', node = params.get('node') || '';
  const countryContinent: Record<string, string> = { CN: 'AS', JP: 'AS', DE: 'EU', FR: 'EU', US: 'NA', CA: 'NA', BR: 'SA', AR: 'SA', ZA: 'AF', EG: 'AF', AU: 'OC', NZ: 'OC' };
  const countryCode = country || /^node_([a-z]{2})_(?:\d{3}|local)$/.exec(node)?.[1]?.toUpperCase() || '';
  const continentCode = continent || countryContinent[countryCode] || '';
  const crumbs: Crumb[] = [];
  if (continentCode && geoNames.continents[continentCode]) crumbs.push({ level: 'continent', id: continentCode, name: geoNames.continents[continentCode] });
  if (countryCode && geoNames.countries[countryCode] && countryContinent[countryCode] === continentCode) crumbs.push({ level: 'country', id: countryCode, name: geoNames.countries[countryCode] });
  if (node && crumbs.at(-1)?.level === 'country' && node.includes(`_${countryCode.toLowerCase()}_`)) crumbs.push({ level: 'node', id: node, name: `${geoNames.countries[countryCode]}节点` });
  return { filters, crumbs };
}
const number = (value: number) => new Intl.NumberFormat('zh-CN').format(value);
const localInput = (iso: string) => { if (!iso) return ''; const date = new Date(iso); return new Date(date.getTime() - date.getTimezoneOffset() * 60_000).toISOString().slice(0, 16); };
function setDraftTime(key: 'from' | 'to', value: string) { draft[key] = value ? new Date(value).toISOString() : ''; }
function queryFor(filters: Filters, crumbs: Crumb[]): GeoQuery { const to = filters.range === 'custom' ? new Date(filters.to) : new Date(), from = filters.range === 'custom' ? new Date(filters.from) : new Date(to.getTime() - ({ '24h': 1, '7d': 7, '30d': 30 }[filters.range] ?? 1) * 86_400_000); const parent = crumbs.at(-1); return { tenantId: filters.tenantId, productId: filters.productId || undefined, status: filters.status as DeviceStatus || undefined, continent: filters.continent || undefined, countryCode: filters.countryCode || undefined, nodeId: filters.nodeId || undefined, from: from.toISOString(), to: to.toISOString(), seed: 42, level: parent?.level ?? 'global', parentId: parent?.id }; }
const initial = initialLocation();
const draft = reactive(initial.filters);
const applied = ref(initial.filters);
const crumbs = ref<Crumb[]>(initial.crumbs);
const role = ref<Role>('platformAdmin');
const scenario = ref<Scenario>('normal');
const themeChoice = ref(localStorage.getItem('iot-atlas-theme') || 'dark');
const media = matchMedia('(prefers-color-scheme: dark)');
const systemDark = ref(media.matches);
const updateSystem = () => { systemDark.value = media.matches; };
media.addEventListener('change', updateSystem);
onBeforeUnmount(() => media.removeEventListener('change', updateSystem));
const dark = computed(() => themeChoice.value === 'dark' || (themeChoice.value === 'system' && systemDark.value));
watch([dark, themeChoice], () => { document.documentElement.dataset.theme = dark.value ? 'dark' : 'light'; localStorage.setItem('iot-atlas-theme', themeChoice.value); }, { immediate: true });
const data = ref<GeoData | null>(null), error = ref(''), loading = ref(true), stale = ref(false), retry = ref(0), view = ref<'map' | 'list'>('map'), selected = ref<GeoItem | null>(null);
const retryable = ref(false);
watch(role, () => { data.value = null; selected.value = null; stale.value = false; }, { flush: 'sync' });
watch(scenario, value => { if (value === 'forbidden') { data.value = null; selected.value = null; stale.value = false; } }, { flush: 'sync' });
const filterError = ref('');
let detailTrigger: HTMLElement | SVGElement | null = null;
function openDetail(item: GeoItem) { const active = document.activeElement; detailTrigger = active instanceof HTMLElement || active instanceof SVGElement ? active : null; selected.value = item; }
function closeDetail() { selected.value = null; const trigger = detailTrigger; detailTrigger = null; requestAnimationFrame(() => trigger?.focus()); }
watch(selected, async item => { if (item) { await nextTick(); document.querySelector<HTMLElement>('.atlas-geography .country-drawer')?.focus(); } });
const onDetailEscape = (event: KeyboardEvent) => { if (event.key === 'Escape' && selected.value) { event.preventDefault(); closeDetail(); } };
window.addEventListener('keydown', onDetailEscape);
onBeforeUnmount(() => window.removeEventListener('keydown', onDetailEscape));
const listSort = ref<GeoSort>('devices'), listDirection = ref<GeoDirection>('desc'), listPage = ref(1);
const list = computed(() => geoListPage(data.value?.items ?? [], listSort.value, listDirection.value, listPage.value));
const visibleView = computed(() => data.value?.mapAvailable ? view.value : 'list');
let request = 0;
watch([applied, crumbs, role, scenario, retry], async () => { const current = ++request; loading.value = true; error.value = ''; const context: Context = { actorId: 'usr_202609_001', role: role.value, tenantId: role.value === 'platformAdmin' ? 'all' : 'ten_202609_001', seed: 42, scenario: scenario.value }; const result = await getTopology(context, queryFor(applied.value, crumbs.value)); if (current !== request) return; if ('error' in result) { error.value = result.error.message; retryable.value = result.error.retryable === true; if (result.error.code === 'FORBIDDEN') { data.value = null; selected.value = null; stale.value = false; } else stale.value = true; } else { data.value = result.data; stale.value = false; retryable.value = false; } loading.value = false; }, { immediate: true });
function choose(item: GeoItem) { if (item.kind === 'device') { openDetail(item); return; } selected.value = null; listPage.value = 1; crumbs.value = [...crumbs.value, { level: item.kind as GeoLevel, id: item.id, name: item.name }]; }
function apply() { if (draft.range === 'custom' && (!draft.from || !draft.to || !Number.isFinite(Date.parse(draft.from)) || !Number.isFinite(Date.parse(draft.to)) || Date.parse(draft.from) >= Date.parse(draft.to) || Date.parse(draft.to) - Date.parse(draft.from) > 30 * 86_400_000)) { filterError.value = '请选择有效的 30 天内 UTC 时间范围'; requestAnimationFrame(() => document.querySelector<HTMLInputElement>(`[aria-label="${!Number.isFinite(Date.parse(draft.from)) ? '开始时间' : '结束时间'}"]`)?.focus()); return; } filterError.value = ''; if (draft.tenantId !== applied.value.tenantId) { data.value = null; stale.value = false; } applied.value = { ...draft }; crumbs.value = []; selected.value = null; listPage.value = 1; }
function reset() { const next = initialFilters(); if (role.value !== 'platformAdmin') next.tenantId = 'ten_202609_001'; Object.assign(draft, next); filterError.value = ''; if (next.tenantId !== applied.value.tenantId) { data.value = null; stale.value = false; } applied.value = next; crumbs.value = []; selected.value = null; listPage.value = 1; }
function goTo(index: number) { crumbs.value = crumbs.value.slice(0, index + 1); selected.value = null; listPage.value = 1; }
function filterLegend(status: string) { const next = { ...applied.value, status }; Object.assign(draft, next); applied.value = next; selected.value = null; listPage.value = 1; }
function sortList(key: GeoSort) { if (listSort.value === key) listDirection.value = listDirection.value === 'asc' ? 'desc' : 'asc'; else { listSort.value = key; listDirection.value = key === 'name' ? 'asc' : 'desc'; } listPage.value = 1; }
</script>
<template>
  <div class="atlas-dashboard atlas-geography"><aside class="atlas-sidebar" aria-label="主导航"><div class="atlas-brand">IoT <strong>Atlas</strong></div><nav><a href="/dashboard">◇ 数据大盘</a><a class="active" href="/geography" aria-current="page">▣ 全球节点</a><a href="/products">◇ 产品与物模型</a><a href="/devices">◇ 设备中心</a><a href="/rules">◇ 规则引擎</a><a href="/firmware">◇ 固件与 OTA</a><a href="/tenants">◇ 租户管理</a><a href="/labs">◇ 实验室</a><a href="/delivery">◇ 交付看板</a></nav><a class="diagnostic-link" href="/">诊断页</a></aside>
    <main class="atlas-workspace"><header class="atlas-header"><div><small>IoT Atlas / 全球节点</small><h1>全球节点</h1><p>从洲、国家到节点与设备；坐标为城市级演示数据。</p></div><div class="header-actions"><label>主题<select v-model="themeChoice" aria-label="主题"><option value="dark">暗色</option><option value="light">亮色</option><option value="system">跟随系统</option></select></label><label>演示身份<select v-model="role" aria-label="演示身份"><option value="platformAdmin">平台管理员</option><option value="tenantAdmin">租户管理员</option><option value="operator">运维工程师</option><option value="viewer">数据观察员</option></select></label></div></header>
      <ElCard class="geo-filters" role="region" aria-label="节点筛选"><h2>筛选条件</h2><div class="geo-filter-grid"><label>租户<select v-model="draft.tenantId" aria-label="租户"><option v-for="(name, id) in tenants" :key="id" :value="id">{{ name }}</option></select></label><label>产品<select v-model="draft.productId" aria-label="产品"><option v-for="(name, id) in products" :key="id" :value="id">{{ name }}</option></select></label><label>状态<select v-model="draft.status" aria-label="状态"><option v-for="(name, id) in statuses" :key="id" :value="id">{{ name }}</option></select></label><label>区域<select v-model="draft.continent" aria-label="区域"><option value="">全部区域</option><option v-for="(name, id) in geoNames.continents" :key="id" :value="id">{{ name }}</option></select></label><label>国家<select v-model="draft.countryCode" aria-label="国家"><option value="">全部国家</option><option v-for="(name, id) in geoNames.countries" :key="id" :value="id">{{ name }}</option></select></label><label>节点<select v-model="draft.nodeId" aria-label="节点"><option value="">全部节点</option><option v-for="(name, id) in geoNames.countries" :key="id" :value="`node_${id.toLowerCase()}_001`">{{ name }}节点</option></select></label><label>时间范围<select v-model="draft.range" aria-label="时间范围"><option value="24h">24 小时</option><option value="7d">7 天</option><option value="30d">30 天</option><option value="custom">自定义</option></select></label><template v-if="draft.range === 'custom'"><label>开始时间<input aria-label="开始时间" type="datetime-local" :aria-invalid="!!filterError && !Number.isFinite(Date.parse(draft.from))" :aria-describedby="filterError ? 'geo-range-error' : undefined" :value="localInput(draft.from)" @change="setDraftTime('from', ($event.target as HTMLInputElement).value)" /></label><label>结束时间<input aria-label="结束时间" type="datetime-local" :aria-invalid="!!filterError && Number.isFinite(Date.parse(draft.from))" :aria-describedby="filterError ? 'geo-range-error' : undefined" :value="localInput(draft.to)" @change="setDraftTime('to', ($event.target as HTMLInputElement).value)" /></label></template><p v-if="filterError" id="geo-range-error" role="alert">{{ filterError }}</p><div class="geo-filter-actions"><ElButton type="primary" :disabled="loading" @click="apply">应用</ElButton><ElButton @click="reset">重置</ElButton></div></div><details class="scenario-control"><summary>演示状态</summary><label>Mock 场景<select v-model="scenario" aria-label="Mock 场景"><option value="normal">正常</option><option value="slow">缓慢</option><option value="partialFailure">地图不可用</option><option value="offline">服务离线</option><option value="forbidden">无权限</option></select></label></details></ElCard>
      <div class="dashboard-feedback" aria-live="polite"><span v-if="loading" role="status">节点数据加载中…</span><span v-if="error" role="alert">{{ error }}{{ stale && data ? '；当前显示上次成功的数据（非最新）' : '' }} <ElButton v-if="retryable" size="small" @click="retry++">重试</ElButton></span><span v-if="data && !data.mapAvailable && !error" role="alert">地图不可用，已切换到同数据的列表视图。</span></div>
      <template v-if="data"><nav class="geo-breadcrumb" aria-label="地理层级"><button @click="goTo(-1)">全球</button><span v-for="(crumb, index) in crumbs" :key="crumb.id"> › <button @click="goTo(index)">{{ crumb.name }}</button></span></nav><div class="geo-summary" aria-label="节点统计"><ElCard>设备 <strong>{{ number(data.summary.devices) }}</strong></ElCard><ElCard>在线 <strong>{{ number(data.summary.onlineDevices) }}</strong></ElCard><ElCard>消息量 <strong>{{ number(data.summary.messages) }}</strong></ElCard><ElCard>告警 <strong>{{ number(data.summary.alarms) }}</strong></ElCard><ElCard>未定位 <strong>{{ number(data.summary.unlocated) }}</strong></ElCard></div>
        <ElCard class="geo-main" role="region"><div class="geo-title"><div><h2>{{ crumbs.at(-1)?.name ?? '全球' }}节点分布</h2><small>地图缩放不改变筛选范围；点击对象下钻。</small></div><div class="geo-switch"><ElButton :type="visibleView === 'map' ? 'primary' : 'default'" :disabled="!data.mapAvailable" @click="view = 'map'">地图视图</ElButton><ElButton :type="visibleView === 'list' ? 'primary' : 'default'" @click="view = 'list'">列表视图</ElButton></div></div><div class="geo-legend" role="group" aria-label="设备状态图例"><button v-for="option in geoLegendOptions" :key="option.status" type="button" :aria-pressed="applied.status === option.status" :disabled="loading" @click="filterLegend(option.status)"><span class="geo-legend-dot" :style="{ backgroundColor: option.color }" />{{ option.label }}</button></div><p v-if="!data.items.length">当前筛选范围没有节点或设备。</p><div v-else class="geo-content"><GeoChart v-if="visibleView === 'map'" :items="data.items" :status="applied.status" @select="item => item.kind === 'node' || item.kind === 'device' ? openDetail(item) : choose(item)" @clear="closeDetail" /><div class="geo-list"><h3>{{ visibleView === 'map' ? '区域与节点列表' : '全部结果' }}</h3><table><thead><tr><th :aria-sort="listSort === 'name' ? listDirection === 'asc' ? 'ascending' : 'descending' : undefined"><button @click="sortList('name')">名称{{ listSort === 'name' ? listDirection === 'asc' ? ' ↑' : ' ↓' : '' }}</button></th><th :aria-sort="listSort === 'devices' ? listDirection === 'asc' ? 'ascending' : 'descending' : undefined"><button @click="sortList('devices')">设备数{{ listSort === 'devices' ? listDirection === 'asc' ? ' ↑' : ' ↓' : '' }}</button></th><th>状态</th><th>详情</th></tr></thead><tbody><tr v-for="item in list.items" :key="item.id"><td><button @click="choose(item)">{{ item.name }}</button></td><td>{{ number(item.devices) }}</td><td>{{ item.status ? statuses[item.status] : `${Math.round((item.onlineRate ?? 0) * 100)}% 在线` }}</td><td><button :aria-label="`查看${item.name}详情`" @click="openDetail(item)">查看</button></td></tr></tbody></table><nav class="geo-pagination" aria-label="节点列表分页"><button :disabled="list.page === 1" @click="listPage = list.page - 1">上一页</button><span>第 {{ list.page }}/{{ list.pages }} 页，共 {{ list.total }} 项</span><button :disabled="list.page === list.pages" @click="listPage = list.page + 1">下一页</button></nav></div></div></ElCard>
        <ElCard class="geo-unlocated" role="region"><h2>未定位设备（{{ data.unlocated.length }}）</h2><p>设备没有坐标时保留在列表中；不会绘制虚构位置。</p><ul v-if="data.unlocated.length"><li v-for="item in data.unlocated" :key="item.id"><button @click="openDetail(item)">{{ item.id }}</button> · {{ geoNames.countries[item.countryCode!] }} · {{ statuses[item.status!] }}</li></ul><p v-else>当前范围没有未定位设备。</p></ElCard>
      </template>
    </main><aside v-if="selected" class="country-drawer" role="dialog" aria-modal="false" tabindex="-1" :aria-label="`${selected.name}详情`"><div class="drawer-head"><h2>{{ selected.name }} · 详情</h2><button aria-label="关闭详情" @click="closeDetail">×</button></div><p>{{ selected.kind === 'device' ? '设备' : selected.kind }} · 城市级演示坐标</p><dl><div v-for="[label, value] in [['ID', selected.id], ['状态', selected.status ? statuses[selected.status] : '聚合'], ['坐标', selected.coordinates ? selected.coordinates.join(', ') : '未定位'], ['在线率', selected.onlineRate === null ? '—' : `${Math.round(selected.onlineRate * 100)}%`], ['设备数', number(selected.devices)], ['消息量', number(selected.messages)], ['告警数', number(selected.alarms)], ['最后活动时间', selected.lastActiveAt ?? '—']]" :key="label"><dt>{{ label }}</dt><dd>{{ value }}</dd></div></dl><a v-if="selected.kind === 'device'" :href="`/devices?device=${encodeURIComponent(selected.id)}`">查看设备详情</a></aside>
  </div>
</template>
